    "title": "SOLO LEVELING",
    "synopsis": "En un mundo contemporáneo repentinamente plagado por la aparición de portales dimensionales infestados de bestias mágicas, Sung Jinwoo es notoriamente conocido como el cazador de rango E más débil y patético de la asociación. Tras sobrevivir milagrosamente como el único remanente de una masacre absoluta en una mazmorra oculta de rango divino, es elegido por un \"Sistema\" invisible. Este programa, proyectado en su visión como un videojuego, le permite \"subir de nivel\" infinitamente mediante misiones, otorgándole un poder necromántico sin precedentes.",
