    "id": "modal-97_fc5e5b25.html",
    "title": "COBRA KAI",
    "synopsis": "Más de treinta años después del clímax del torneo All Valley de 1984, un fracasado y alcoholizado Johnny Lawrence busca la redención reabriendo el polémico y agresivo dojo de karate Cobra Kai. Esta acción reaviva inmediatamente su histórica e inmadura rivalidad con un ahora altamente exitoso y pomposo Daniel LaRusso. El conflicto intergeneracional escala rápidamente mientras ambos enseñan filosofías de karate opuestas a un nuevo y vulnerable grupo de adolescentes, quienes pronto se ven inmersos en violentas riñas de instituto y pandillas de dojos.",
